package com.example

import com.example.ExamQuestionHelper.QSpec

internal object ArtLiveExamTheoryColorBank1 {
    private const val T = "චිත්‍ර කලා මූලිකාංග, නිර්මාණ මූලධර්ම හා වර්ණ න්‍යාය"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("දෘශ්‍ය කලාවේ 'මූලිකාංග' (Elements of Art) හතට අයත් නොවන පදය කුමක්ද?", "සමතුලිතතාව (Balance)", "රේඛාව (Line)", "හැඩය (Shape)", "වර්ණය (Color)", "සමතුලිතතාව යනු කලා මූලධර්මයක් (Principle) මිස රේඛාව, හැඩය, ආකෘතිය, වර්ණය, තානය, වයනය හා අවකාශය වැනි මූලිකාංගයක් නොවේ."),
        q("චිත්‍ර කලාවේ මූලිකම හා සරලම ආරම්භක අංගය ලෙස සැලකෙන 'රේඛාව' (Line) නිර්වචනය කරන්නේ කෙසේද?", "චලනය වන තිතකින් සෑදෙන අඛණ්ඩ සලකුණ", "වර්ණ තුනක මිශ්‍රණයක්", "ත්‍රිමාණ ගල් කුට්ටියක්", "පසුබිම් රාමුවේ බර", "කඩදාසිය මත පැන්සලක් හෝ පින්සලක් චලනය වීමෙන් ඇති වන සලකුණ රේඛාව නම් වේ."),
        q("චිත්‍රයක 'සිරස් රේඛා' (Vertical Lines) බහුලව යෙදීමෙන් නරඹන්නා තුළ ජනිත වන හැඟීම කුමක්ද?", "ශක්තිය, උසස් බව, ස්ථාවරත්වය", "වේගවත් කලබලකාරී කඩාවැටීම", "නිදාගත් නිසල තැනිතලා බව", "සැහැල්ලු විනෝදකාමී හාස්‍යය", "උස් ගස් හා දෙව්මැදුරු කුළුණු මෙන් සිරස් රේඛා ශක්තිය හා ආධ්‍යාත්මික උසස් බව දනවයි."),
        q("චිත්‍රයක 'තිරස් රේඛා' (Horizontal Lines) මගින් ප්‍රකාශ වන ප්‍රධාන මනෝභාවය කුමක්ද?", "සාමකාමී නිසල බව හා විවේකය", "දැඩි භය හා මානසික කැළඹීම", "වේගවත් චලනය හා ධාවනය", "අසමතුලිතව කඩා වැටීමේ බිය", "නිසල සාගර ක්ෂිතිජය මෙන් තිරස් රේඛා නරඹන්නාට සන්සුන් හා සාමකාමී හැඟීමක් ලබා දෙයි."),
        q("චිත්‍ර සංයුතියක 'විකර්ණ රේඛා' (Diagonal Lines) භාවිත කිරීමෙන් ලැබෙන ප්‍රධාන දෘශ්‍ය බලපෑම කුමක්ද?", "චලනය, ජවය හා වේගවත් බව", "නිසල ගැඹුරු නින්දේ හැඟීම", "සම්පූර්ණ නිශ්චල ස්ථාවර බව", "වර්ණ ස්තර අඳුරු වී යාම", "ඇල වූ රේඛා වැටීමට හෝ චලනය වීමට ආසන්න හැඟීමක් දෙන නිසා ගතික ජවය මැවේ."),
        q("වක්‍ර රේඛා (Curved / Organic Lines) බොහෝ විට සිතුවමක කුමන ගුණාංගයක් මතු කිරීමට උපකාරී වේද?", "මෘදු බව, ලාලිත්‍යය, ස්වභාවික රිද්මය හා සුන්දරත්වය", "යකඩ වැනි තද කර්කශ බව", "විදුලි කෙටීම් වැනි කම්පනය", "සීතල ගණිත කොටු බව", "සීගිරි සිතුවම් හා ලියවැල් මෝස්තරවල වක්‍ර රේඛා සජීවී ලාලිත්‍යය ගෙන එයි."),
        q("රේඛාවක් තමන්ගේම ආරම්භක ලක්ෂ්‍යය හමු වී වටකුරු වී සෑදෙන 'ද්විමාන' (2D - දිග සහ පළල පමණක් ඇති) ප්‍රදේශය කුමක්ද?", "හැඩය (Shape)", "ආකෘතිය (Form)", "වයනය (Texture)", "තානය (Tone)", "වෘත්තය, චතුරස්‍රය හෝ ශාක කොළයක පැතලි සටහන ද්විමාන හැඩයක් ලෙස හැඳින්වේ."),
        q("හැඩය (Shape) සහ ආකෘතිය (Form) අතර ඇති ප්‍රධාන වෙනස කුමක්ද?", "හැඩය ද්විමාන (2D) වන අතර ආකෘතිය ත්‍රිමාන (3D - දිග, පළල සහ ගැඹුර) වේ", "හැඩය කළු පමණක් වන අතර ආකෘතිය රතු වේ", "හැඩය මූර්තියක් වන අතර ආකෘතිය චිත්‍රයකි", "දෙක අතර කිසිදු වෙනසක් නැත", "වෘත්තය හැඩයක් වන විට ගෝලය ආකෘතියකි; චතුරස්‍රය හැඩයක් වන විට ඝනකය ආකෘතියකි."),
        q("ද්විමාන හැඩතල ප්‍රධාන කොටස් දෙකකට බෙදෙනු ලබන්නේ කෙසේද?", "ජ්‍යාමිතික හැඩතල (Geometric) සහ ජෛවමය/ස්වභාවික හැඩතල (Organic)", "උණුසුම් හැඩතල සහ සිසිල් හැඩතල", "ප්‍රාථමික හැඩතල සහ ද්විතීයික හැඩතල", "තෙත් හැඩතල සහ වියළි හැඩතල", "රවුම්, කොටු, ත්‍රිකෝණ ජ්‍යාමිතික වන අතර වලාකුළු, කොළ හා ගල්වල හැඩ ස්වභාවික ජෛව හැඩ වේ."),
        q("චිත්‍රයක ප්‍රධාන වස්තූන් හා රූප මගින් අල්ලාගෙන ඇති ඉඩ 'ධන අවකාශය' (Positive Space) වන අතර ඒවා වටා ඇති හිස් පසුබිම කුමක්ද?", "සෘණ අවකාශය (Negative Space)", "ඝන අවකාශය", "රේඛීය අවකාශය", "උණුසුම් අවකාශය", "ධන අවකාශය මෙන්ම සෘණ අවකාශයද සිතුවමේ සමබරතාව හා පැහැදිලි බව රැකීමට අතිශය වැදගත්ය."),
        q("චිත්‍ර කලාවේ 'තානය' හෙවත් 'අගය' (Value / Tone) යන මූලිකාංගයෙන් අදහස් කරන්නේ කුමක්ද?", "වර්ණයක ආලෝක හා අඳුරු මට්ටම්", "වස්තුවක භෞතික බර ප්‍රමාණය", "සිතුවමේ වෙළඳපොළ වටිනාකම", "කැන්වසයේ සම්පූර්ණ දිග හා පළල", "සෙවණැලි හා ආලෝකය දැක්වීමෙන් ද්විමාන හැඩයකට ත්‍රිමාණ ගැඹුරක් ලබා දීමට තානය යොදා ගනී."),
        q("වස්තුවක් මතට ආලෝකය වැටුණු විට පෙනෙන ඉතාම දීප්තිමත් ස්ථානය හා ඊට විරුද්ධ පැත්තේ පොළොවට වැටෙන සෙවණැල්ල පිළිවෙළින් මොනවාද?", "උච්ච ආලෝකය හා පතිත සෙවණැල්ල", "ආලෝක තානය සහ රළු වයනය", "බාහිර රේඛාව සහ පැතලි හැඩය", "උණුසුම් වර්ණය හා සිසිල් වර්ණය", "ගෝලයක මුදුනට ආලෝකය වැටෙන තැන හයිලයිට් වන අතර බිමට වැටෙන අඳුර කාස්ට් ෂැඩෝ වේ."),
        q("චිත්‍රයක හෝ මූර්තියක මතුපිට ඇති සිනිඳු බව, රළු බව, ගොරෝසු බව හෝ මෘදු බව දැනෙන ගුණාංගය කුමක්ද?", "වයනය (Texture)", "අවකාශය", "සමමිතිය", "වර්ණ චක්‍රය", "අතින් ඇල්ලීමේදී දැනෙන සැබෑ වයනය (Actual Texture) හා ඇසින් පෙනෙන මායා වයනය (Implied Texture) ලෙස දෙකකි."),
        q("වර්ණ න්‍යායේදී වෙනත් වර්ණ දෙකක් මිශ්‍ර කිරීමෙන් සාදා ගත නොහැකි 'ප්‍රාථමික වර්ණ' (Primary Colors - RYB චිත්‍ර කලාවේ) තුන මොනවාද?", "රතු, කහ සහ නිල් (Red, Yellow, Blue)", "කොළ, තැඹිලි සහ දම්", "කළු, සුදු සහ අළු", "රෝස, දුඹුරු සහ රන්", "චිත්‍ර කලාවේ සාම්ප්‍රදායික වර්ණ චක්‍රයේ සෙසු සියලු වර්ණ සෑදීමට රතු, කහ හා නිල් මූලික වේ."),
        q("ප්‍රාථමික වර්ණ දෙකක් සමාන ප්‍රමාණයෙන් මිශ්‍ර කිරීමෙන් ලැබෙන 'ද්විතීයික වර්ණ' (Secondary Colors) තුන මොනවාද?", "තැඹිලි, කොළ සහ දම් (Orange, Green, Violet)", "රතු, කහ සහ නිල්", "කළු, සුදු සහ දුඹුරු", "තද නිල්, තද රතු සහ තද කහ", "රතු+කහ=තැඹිලි, කහ+නිල්=කොළ, නිල්+රතු=දම් ලෙස ද්විතීයික වර්ණ බිහිවේ."),
        q("ප්‍රාථමික වර්ණයක් සහ ඊට යාබද ද්විතීයික වර්ණයක් මිශ්‍ර කිරීමෙන් සෑදෙන 'තෘතීයික වර්ණ' (Tertiary Colors) වලට නිවැරදි උදාහරණයක් කුමක්ද?", "රතු-තැඹිලි, කහ-කොළ හෝ නිල්-දම්", "සම්පූර්ණ කළු සහ සුදු", "රතු සහ නිල් පමණක්", "කහ සහ තැඹිලි නොව රිදී", "සම්මත වර්ණ චක්‍රයේ වර්ණ 12න් 6ක් තෘතීයික වර්ණ වේ (උදා: Blue-Green, Red-Violet)."),
        q("වර්ණ චක්‍රයේ එකිනෙකට කෙළින්ම ප්‍රතිවිරුද්ධ පැතිවල පිහිටි වර්ණ යුගල හඳුන්වන්නේ කුමන නමින්ද?", "අනුපූරක වර්ණ (Complementary Colors)", "සමීප වර්ණ (Analogous)", "ඒකවර්ණ (Monochromatic)", "උදාසීන වර්ණ (Neutral)", "රතු-කොළ, නිල්-තැඹිලි සහ කහ-දම් යන යුගල එකිනෙක ළඟ තැබූ විට උපරිම දීප්තියක් ලැබේ."),
        q("වර්ණ න්‍යායේදී එක ළඟ පිහිටි වර්ණ තුනක් හෝ හතරක් (උදා: කහ, කහ-කොළ, කොළ) යොදා කරන සංයෝජනය කුමක්ද?", "සමීප වර්ණ සංයෝජනය (Analogous)", "අනුපූරක වර්ණ සංයෝජනය", "ත්‍රිකෝණාකාර වර්ණ සංයෝජනය", "ඒකවර්ණ තාන සංයෝජනය", "එකම වර්ණ පවුලකට අයත් යාබද වර්ණ භාවිතය නිසා සිතුවමේ ස්වභාවික සමගිය හා සන්සුන් බව රැකේ."),
        q("එකම මූලික වර්ණයකට සුදු හෝ කළු මිශ්‍ර කර ලබා ගන්නා විවිධ එළි හා අඳුරු ප්‍රභේද පමණක් යොදා අඳින සිතුවම අයත් වන්නේ කුමන වර්ණ ක්‍රමයටද?", "ඒකවර්ණ සංයෝජනය (Monochromatic)", "ත්‍රිකෝණාකාර වර්ණ සංයෝජනය", "අනුපූරක වර්ණ සංයෝජනය", "බහුවර්ණ දේදුනු සංයෝජනය", "උදාහරණයක් ලෙස නිල් වර්ණය පමණක් සුදු හා කළු සමඟ මිශ්‍ර කර ඇඳීම ඒකවර්ණ ක්‍රමයයි."),
        q("මූලික වර්ණයකට (Hue) 'සුදු' වර්ණය මිශ්‍ර කිරීමෙන් ලැබෙන ලා පැහැය සහ 'කළු' වර්ණය මිශ්‍ර කිරීමෙන් ලැබෙන අඳුරු පැහැය පිළිවෙළින් මොනවාද?", "ටින්ට් (Tint) සහ ෂේඩ් (Shade)", "ටෝන් (Tone) සහ ෂේඩ්", "උණුසුම් සහ සිසිල්", "ප්‍රාථමික සහ ද්විතීයික", "වර්ණයකට සුදු දැමීම ටින්ට් (Tint), කළු දැමීම ෂේඩ් (Shade) සහ අළු දැමීම ටෝන් (Tone) වේ."),
        q("වර්ණයකට 'අළු' (Grey - කළු+සුදු) මිශ්‍ර කළ විට එම වර්ණයේ දීප්තිය අඩු වී ලැබෙන ප්‍රභේදය කුමක්ද?", "ටෝන් (Tone)", "ටින්ට් (Tint)", "හියු (Hue)", "ප්‍රාථමික වර්ණය", "වර්ණ තීව්‍රතාව හෙවත් සංතෘප්තිය අඩු කර මෘදු පෙනුමක් ගැනීමට අළු මිශ්‍ර කර ටෝන් සාදයි."),
        q("වර්ණ චක්‍රයේ 'උණුසුම් වර්ණ' (Warm Colors) ලෙස හඳුන්වන වර්ණ කාණ්ඩය කුමක්ද?", "රතු, තැඹිලි සහ කහ", "නිල්, කොළ සහ දම්", "කළු, සුදු සහ අළු", "රිදී සහ ලා නිල්", "උණුසුම් වර්ණ චිත්‍රයේ ඉදිරියට පැන පෙනෙන ස්වභාවයක් (Advancing) හා උද්යෝගය දක්වයි."),
        q("වර්ණ චක්‍රයේ 'සිසිල් වර්ණ' (Cool Colors) ලෙස හඳුන්වන වර්ණ මොනවාද?", "නිල්, කොළ සහ දම්", "රතු, තැඹිලි සහ රන්", "තද රෝස සහ කහ", "රතු-තැඹිලි සහ දුඹුරු", "සිසිල් වර්ණ චිත්‍රයේ පසුපසට පසුබැසී පෙනෙන ස්වභාවයක් (Receding) හා සන්සුන් බව ගෙන එයි."),
        q("චිත්‍රයක දුර හා ළඟ පෙන්වීමට වර්ණ භාවිත කරන විට පසුබිමට යොදන්නේ කුමන වර්ණද?", "ලා සිසිල් වර්ණ පසුබිමට යෙදීම", "පසුබිමට දීප්තිමත් රතු යෙදීම", "සෑම තැනම තද කළු ගෑම", "පසුබිමට තද තැඹිලි යෙදීම", "උණුසුම් වර්ණ ඇසට ඉක්මනින් ළං වන අතර සිසිල් වර්ණ දුරස්ථ ගැඹුරක් නිර්මාණය කරයි."),
        q("වර්ණයක පිරිසිදු නම (උදා: රතු, නිල්, කොළ) හා එහි දීප්තිමත්/තීව්‍ර බව හඳුන්වන තාක්ෂණික පද දෙක පිළිවෙළින් මොනවාද?", "හියු (Hue) සහ සංතෘප්තිය", "වයනය සහ සෘණ අවකාශය", "සමමිතිය සහ දෘශ්‍ය රිද්මය", "ටින්ට් (Tint) සහ ෂේඩ්", "වර්ණයක ප්‍රධාන ලක්ෂණ තුන වන්නේ Hue (වර්ණ නම), Value (එළි-අඳුරු බව) සහ Intensity (තීව්‍රතාව) ය."),
        q("සම්පූර්ණ වර්ණ නොවන 'උදාසීන වර්ණ' (Neutral Colors) ලෙස සැලකෙන්නේ මොනවාද?", "කළු, සුදු, අළු සහ ඇතැම් විට දුඹුරු", "රතු, කහ සහ නිල්", "කොළ සහ තැඹිලි", "දම් සහ රෝස", "වර්ණ චක්‍රයේ නොපිහිටන කළු, සුදු හා අළු වෙනත් වර්ණවල තානය වෙනස් කිරීමට යොදා ගනී."),
        q("වර්ණ චක්‍රයේ සමාන දුරකින් පිහිටා ත්‍රිකෝණයක් සාදන වර්ණ තුනක් (උදා: තැඹිලි, කොළ, දම්) යොදාගන්නා වර්ණ සැලැස්ම කුමක්ද?", "ත්‍රිකෝණාකාර වර්ණ සංයෝජනය", "ඒකවර්ණ තාන සංයෝජනය", "සමීප අනුරූප වර්ණ සංයෝජනය", "උදාසීන කළු-සුදු සංයෝජනය", "ත්‍රිකෝණාකාර සංයෝජනය සිතුවමට ප්‍රබල සමතුලිතතාවක් හා දීප්තිමත් විචිත්‍රත්වයක් ගෙන දෙයි."),
        q("අනුපූරක වර්ණ දෙකක් (උදා: රතු සහ කොළ) පැලට්ටුව මත එකට මිශ්‍ර කළහොත් ලැබෙන වර්ණය කුමක්ද?", "මඩ පැහැති දුඹුරු හෝ අළු", "අතිශය දීප්තිමත් රත්රන් පැහැය", "පිරිසිදු සුදු වර්ණය", "තද දීප්තිමත් නිල් පැහැය", "ප්‍රතිවිරුද්ධ වර්ණ යාබදව තැබූ විට දීප්තිමත් වුවත් එකට මිශ්‍ර කළ විට එකිනෙක නිෂේධනය කර අළු/දුඹුරු වේ."),
        q("මූලික වර්ණයක් සහ එහි ප්‍රතිවිරුද්ධ වර්ණයට දෙපසින් ඇති වර්ණ දෙක තෝරා ගන්නා සංයෝජනය (උදා: රතු සමඟ කහ-කොළ සහ නිල්-කොළ) කුමක්ද?", "බෙදුණු අනුපූරක සංයෝජනය", "ඒකවර්ණ තාන සංයෝජනය", "ප්‍රාථමික වර්ණ සංයෝජනය", "උදාසීන අළු-කළු සංයෝජනය", "සෘජු අනුපූරක සංයෝජනයට වඩා මෘදු ආතතියක් හා පොහොසත් විවිධත්වයක් මෙමගින් ලැබේ."),
        q("චිත්‍රයක මධ්‍ය රේඛාව දෙපස බර හා අංග සමානව පිහිටුවීමේ නිර්මාණ මූලධර්මය කුමක්ද?", "සමතුලිතතාව (Balance)", "රිද්මය (Rhythm)", "අවධාරණය (Emphasis)", "විවිධත්වය (Variety)", "දෘශ්‍ය භාරය අනුව සිතුවම ඇල නොවී ස්ථාවරව පවත්වා ගැනීම සමතුලිතතාවයි."),
        q("මධ්‍ය අක්ෂය දෙපස හරියටම කැඩපත් ප්‍රතිබිම්බයක් මෙන් සමාන අංග තැබීම හඳුන්වන සමතුලිතතා වර්ගය කුමක්ද?", "සමමිතික සමතුලිතතාව (Symmetrical)", "අසමමිතික සමතුලිතතාව", "අරීය කේන්ද්‍රීය සමතුලිතතාව", "ගතික අවිධිමත් විසිරීම", "දේවාල දොරටු, සඳකඩපහණ හා ටජ් මහල් වැනි නිර්මාණවල විධිමත් සමමිතික සමතුලිතතාව දක්නට ඇත."),
        q("මධ්‍ය ලක්ෂ්‍යයක සිට වටේට රෝදයක ගරාදි මෙන් හෝ පිපුණු මලක පෙති මෙන් විහිදෙන සමතුලිතතාව කුමක්ද?", "අරීය සමතුලිතතාව (Radial Balance)", "සිරස් සමතුලිතතාව", "විකර්ණ අසමතුලිතතාව", "තිරස් රේඛාව", "මණ්ඩල, සීන මල්, ධර්මචක්‍ර හා ගොතික් රෝස කවුළු අරීය සමතුලිතතාවට හොඳම නිදසුන් වේ."),
        q("එක් පසෙක විශාල සැහැල්ලු වස්තුවක්ද අනෙක් පස කුඩා තද වර්ණ වස්තුවක්ද තබා දෘශ්‍ය භාරය සම කිරීමේ ක්‍රමය කුමක්ද?", "අසමමිතික සමතුලිතතාව (Asymmetrical Balance)", "සමමිතික සමතුලිතතාව", "අරීය සමතුලිතතාව", "ඒකවර්ණ සමතුලිතතාව", "සමමිතියෙන් තොර වුවද නරඹන්නාගේ ඇසට සමබර හැඟීමක් දෙන අසමමිතික බව නිර්මාණයට ජීවයක් දෙයි."),
        q("සිතුවමේ නරඹන්නාගේ ඇස මුලින්ම ආකර්ෂණය කර ගන්නා ප්‍රධාන නාභිගත ස්ථානය (Focal Point) ගොඩනගන මූලධර්මය කුමක්ද?", "අවධාරණය හෙවත් ප්‍රමුඛත්වය", "ඒකාකාරී සමපාත බව", "මතුපිට රළු වයනය", "සෘණ හිස් අවකාශය", "ප්‍රතිවිරුද්ධ වර්ණයක්, ප්‍රමාණයෙන් විශාල බවක් හෝ ආලෝකයක් යොදා ප්‍රධාන අරමුණ ඉස්මතු කරයි."),
        q("චිත්‍රයක එකම හැඩතල, වර්ණ හෝ රේඛා ක්‍රමවත්ව නැවත නැවත යෙදීමෙන් නරඹන්නාගේ ඇස චිත්‍රය පුරා ගෙන යන මූලධර්මය කුමක්ද?", "රිද්මය සහ පුනරාවර්තනය", "ස්ථිතික නිහඬ ස්ථාවර බව", "සෘණ අවකාශය කපා ඉවත් කිරීම", "ඒකවර්ණ තාන අඩු කිරීම", "සංගීතයේ තාලය මෙන් රේඛා හා මෝස්තර පුනරාවර්තනය වීමෙන් දෘශ්‍ය රිද්මයක් ගොඩනැගේ."),
        q("සිතුවමක සියලු කොටස් වෙන්ව ගිය කෑලි මෙන් නොපෙනී එකම සමස්ත නිර්මාණයක් ලෙස එකට බැඳී පෙනීමේ ගුණාංගය කුමක්ද?", "ඒකීයත්වය හා සමගිය (Unity)", "හැඩතල අහඹු ලෙස විසිරී යාම", "අසංවිධිත තදබද ස්වභාවය", "වර්ණ අතර තීව්‍ර ගැටුම", "සමාන වර්ණ පවුල්, පුනරාවර්තන හැඩ හා හොඳ සංයුතියකින් චිත්‍රයේ ඒකීයත්වය ඇති වේ."),
        q("සිතුවමක් ඒකාකාරී හා නීරස වීම වැළැක්වීම සඳහා වෙනස් හැඩ, ප්‍රමාණ හා වර්ණ එකතු කිරීමේ මූලධර්මය කුමක්ද?", "විවිධත්වය (Variety)", "ඒකතානතාව", "හිස්බව", "සම්පූර්ණ සමානත්වය", "ඒකීයත්වය සහ විවිධත්වය අතර මනා තුලනයක් පැවතීම සාර්ථක කලා කෘතියක ලක්ෂණයකි."),
        q("ආලෝකය සහ අඳුර, රළු සහ සිනිඳු, විශාල සහ කුඩා වැනි ප්‍රතිවිරුද්ධ අංග එක ළඟ තබා වෙනස කැපී පෙනෙන්නට සැලැස්වීම කුමක්ද?", "ප්‍රතිවිරෝධතාව (Contrast)", "සමානුපාතය", "සමමිතිය", "මිශ්‍රණය", "තියුණු ප්‍රතිවිරෝධතාව මගින් චිත්‍රයේ වැදගත් කොටස් ඉස්මතු වී නරඹන්නාගේ අවධානය රඳවා ගනී."),
        q("කලා කෘතියක එක් කොටසක ප්‍රමාණය තවත් කොටසක හෝ සමස්තයේ ප්‍රමාණය සමඟ ඇති සබඳතාව හඳුන්වන මූලධර්මය කුමක්ද?", "පරිමාණය සහ සමානුපාතය", "මතුපිට වයන විවිධත්වය", "පුනරාවර්තන රේඛීය රිද්මය", "අනුපූරක වර්ණ ප්‍රතිවිරෝධය", "මිනිස් මුහුණේ ඇස්, නාසය හා කට පිහිටීමේදී සමානුපාතය ඉතා වැදගත් වේ."),
        q("චිත්‍ර සංයුතියේදී (Composition) නාභිගත වස්තුව හරි මැද නොතබා සිතුවම් තලය සිරස්ව හා තිරස්ව 3×3 කොටස්වලට බෙදා රේඛා කැපෙන තැනක තැබීමේ රීතිය කුමක්ද?", "තුනෙන් එකේ රීතිය (Rule of Thirds)", "මධ්‍ය ලක්ෂ්‍ය රීතිය", "සමමිතික රීතිය", "පලාපෙති රීතිය", "වඩාත් ස්වභාවික හා රසවත් සංයුතියක් ගොඩනැගීමට ක්ෂිතිජය හා ප්‍රධාන වස්තුව තුනෙන් පංගු රේඛාවල තබයි."),
        q("පැන්සල් සෙවණැලි කිරීමේදී (Shading) සමාන්තර ඉරි සමූහයක් ඇඳීම සහ ඒ මත විරුද්ධ දිශාවට ඉරි කපා ඇඳීම හඳුන්වන ක්‍රම දෙක කවරේද?", "හැචිං (Hatching) සහ ක්‍රොස්-හැචිං (Cross-Hatching)", "ස්ටිප්ලිං සහ ස්මජිං", "ඉම්පැස්ටෝ සහ ග්ලේසිං", "ෆ්‍රෙස්කෝ සහ ටෙම්පරා", "තනි අතට ඉරි ගැසීම හැචිං වන අතර දැලක් මෙන් හරස් ඉරි ගැසීම ක්‍රොස්-හැචිං වේ."),
        q("කුඩා තිත් ලං ලංව හෝ ඈත්ව තැබීමෙන් වස්තුවක අඳුරු-එළි තානය මතු කිරීමේ පෑන් හෝ පැන්සල් ශිල්පය කුමක්ද?", "ස්ටිප්ලිං (Stippling)", "බ්ලෙන්ඩිං (Blending)", "ස්ක්‍රැෆිටෝ", "කොලාජ්", "තද සෙවණැලි ඇති තැන ඉතා ළඟින් වැඩි තිත් ප්‍රමාණයක් තබා ආලෝකය ඇති තැන තිත් අඩු කරයි."),
        q("ආලෝක පරාවර්තනයේදී (Additive RGB - ආලෝක තිර හා කැමරා) ප්‍රාථමික වර්ණ ලෙස ගන්නේ කවර වර්ණ තුනද?", "රතු, කොළ සහ නිල් (RGB)", "රතු, කහ සහ නිල්", "කළු, සුදු සහ අළු", "සයන්, මැජෙන්ටා සහ කහ", "චිත්‍ර වර්ණක (RYB) සහ මුද්‍රණ තීන්ත (CMYK) වලට වෙනස්ව ආලෝක මාධ්‍යවල ප්‍රාථමික වර්ණ RGB වේ."),
        q("වර්ණ මුද්‍රණ කර්මාන්තයේදී (Offset / Digital Printing) භාවිත කරන ප්‍රධාන තීන්ත වර්ණ හතර කුමක්ද?", "සයන්, මැජෙන්ටා, කහ සහ කළු (CMYK)", "රතු, කොළ, නිල් සහ සුදු", "තැඹිලි, දම්, දුඹුරු සහ රන්", "කහ, කොළ, රතු සහ අළු", "කඩදාසි මත වර්ණ මුද්‍රණයේදී CMYK අවශෝෂක වර්ණ පද්ධතිය යොදා ගනී."),
        q("චිත්‍රයක භාවිත කරන 'සංකේතාත්මක වර්ණ' අතරින් 'සෞභාග්‍යය, රාජකීයත්වය හා ධනය' බොහෝ විට සංකේතවත් කරන වර්ණය කුමක්ද?", "දම් (Purple) සහ රන්වන් කහ වර්ණය", "අඳුරු අළු වර්ණය", "තනි කළු වර්ණය", "සුදුමැලි බොර වර්ණය", "අතීතයේ සිට දම් හා රන් පැහැයන් රාජකීය හා ආධ්‍යාත්මික ගෞරවය සංකේතවත් කිරීමට යොදාගෙන ඇත."),
        q("සිතුවමක 'චලනය' (Movement) යන නිර්මාණ මූලධර්මය ක්‍රියාත්මක වන ආකාරය කෙබඳුද?", "නරඹන්නාගේ දෑස ක්‍රමවත්ව මෙහෙයවීම", "කැන්වසය බිත්තිය මත සෙලවීම", "රාමුව කැඩී පිටතට යාම", "සිතුවම මත ජලය ඉස හැරීම", "ගලන ගඟක්, වක්‍ර මාවතක් හෝ විකර්ණ රේඛා මගින් ඇස චිත්‍රයේ ප්‍රධාන තැනට යොමු කෙරේ."),
        q("මෝස්තර නිර්මාණයේදී (Design) තිරස් හා සිරස් අතට සමාන අන්තරයකින් නැවත නැවත යෙදෙන ඒකකය (Motif) හරහා ගොඩනැගෙන්නේ කුමක්ද?", "රටාව (Pattern)", "ඒකලක්ෂ්‍ය දෘෂ්ටිකෝණය", "ස්ෆුමාටෝ", "ටෙනෙබ්‍රිසම්", "ලියවැල්, පලාපෙති හා බතික් රෙදිවල මූලික ඒකකය (Motif) පුනරාවර්තනය වීමෙන් රටාවක් සෑදේ."),
        q("රේඛාවේ ගුණාංග අතර 'සමෝච්ඡ රේඛාව' (Contour Line) යනුවෙන් හඳුන්වන්නේ කුමක්ද?", "පිටත දාරය හා සීමා දක්වන රේඛාව", "සෙවණැලි ඇඳීමට ගහන හරස් ඉරි", "කඩදාසියේ කෙළවර කපන රේඛාව", "පැන්සලෙන් මකා දමන රේඛාව", "වස්තුව දෙස බලාගෙන සෙවණැලි නොදමා බාහිර හා අභ්‍යන්තර හැඩය පෙන්වන රේඛාව සමෝච්ඡ රේඛාවයි."),
        q("චිත්‍රයක පසුබිම සහ පෙරබිම අතර පැහැදිලි වෙනසක් (Figure-Ground Relationship) පවත්වා ගැනීමට වැදගත් වන්නේ කුමක්ද?", "තාන හා වර්ණ ප්‍රතිවිරෝධතාව තැබීම", "වස්තුවත් පසුබිමත් එකම පැහැයෙන් ගෑම", "පසුබිම සම්පූර්ණයෙන් කපා ඉවත් කිරීම", "රේඛා සියල්ල මකා දමා තැබීම", "රූපය පසුබිමේ ගිලී නොයා පැහැදිලිව ඉස්මතු වීමට තාන හා වර්ණ වෙනස අවශ්‍ය වේ."),
        q("චිත්‍ර කලා නිර්මාණයක මූලිකාංග (Elements) සහ මූලධර්ම (Principles) අතර සම්බන්ධය වඩාත් හොඳින් පැහැදිලි කරන උපමාව කුමක්ද?", "අමුද්‍රව්‍ය සහ ඒවා ගළපන ක්‍රමවේදය", "දෙකම එකම වර්ණ කුඩු වර්ගයකි", "චිත්‍ර රාමුව සහ බිත්ති ඇණයයි", "ඒවාට කිසිදු සම්බන්ධයක් නැත", "රේඛා, හැඩ, වර්ණ යන අමුද්‍රව්‍ය සමතුලිතතාව, රිද්මය හා අවධාරණය යන නීති අනුව සංයෝජනය කරයි.")
    )
}
